    if(is_dir($fixture.'-private')){if(is_file($fixture.'-private/security.key'))unlink($fixture.'-private/security.key');rmdir($fixture.'-private');}
    foreach(array_diff($pdo->query('SELECT throttle_key FROM auth_throttle')->fetchAll(PDO::FETCH_COLUMN),$before) as $hash)$pdo->prepare('DELETE FROM auth_throttle WHERE throttle_key=?')->execute([$hash]);if(session_status()===PHP_SESSION_ACTIVE)session_write_close();
    $walk=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($fixture,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::CHILD_FIRST);foreach($walk as $entry){if($entry->isLink()||$entry->isFile())unlink($entry->getPathname());else rmdir($entry->getPathname());}rmdir($fixture);
}
echo count($checks).' session-security checks '.($failed?'before failure':'passed')."\n";exit($failed?1:0);
